func TestDiscovery_ListWithState(t *testing.T) {
	t.Parallel()

	repo, _ := createTestRepo(t)
	store := NewStore(repo)
	state := NewStateManager(repo)
	discovery := NewDiscovery(repo)
	ctx := context.Background()

	// Create some trails
