	t.Parallel()

	id1, err := GenerateTrailID()
	if err != nil {
		t.Fatalf("GenerateTrailID() error = %v", err)
	}

	id2, err := GenerateTrailID()
	if err != nil {
		t.Fatalf("GenerateTrailID() error = %v", err)
	}

	if id1 == id2 {
		t.Error("GenerateTrailID() generated duplicate IDs")
	}

	if len(id1) != 12 {
		t.Errorf("GenerateTrailID() length = %d, want 12", len(id1))
	}
}

