package trail

import (
	"context"
	"errors"
	"os"
	"testing"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

func TestTrailID_Validation(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		id      string
		wantErr bool
	}{
		{"valid 12 hex chars", "a1b2c3d4e5f6", false},
		{"valid all zeros", "000000000000", false},
		{"valid all f's", "ffffffffffff", false},
		{"too short", "a1b2c3d4e5f", true},
		{"too long", "a1b2c3d4e5f6a", true},
		{"uppercase hex", "A1B2C3D4E5F6", true},
		{"non-hex chars", "g1b2c3d4e5f6", true},
		{"empty", "", true},
		{"with dashes", "a1b2-c3d4-e5f6", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			_, err := NewTrailID(tt.id)
			if (err != nil) != tt.wantErr {
				t.Errorf("NewTrailID(%q) error = %v, wantErr %v", tt.id, err, tt.wantErr)
			}
		})
	}
}

func TestTrailID_Generate(t *testing.T) {
	t.Parallel()

	id1, err := GenerateTrailID()
	if err != nil {
		t.Fatalf("GenerateTrailID() error = %v", err)
	}

	id2, err := GenerateTrailID()
	if err != nil {
		t.Fatalf("GenerateTrailID() error = %v", err)
	}

	if id1 == id2 {
		t.Error("GenerateTrailID() generated duplicate IDs")
	}

	if len(id1) != 12 {
		t.Errorf("GenerateTrailID() length = %d, want 12", len(id1))
	}
}

func TestTrailID_Short(t *testing.T) {
	t.Parallel()

	id := TrailID("a1b2c3d4e5f6")
	if got := id.Short(); got != "a1b2c3d4" {
		t.Errorf("Short() = %q, want %q", got, "a1b2c3d4")
	}
}

func TestTrail_Validate(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		trail   Trail
		wantErr bool
	}{
		{
			name: "valid trail",
			trail: Trail{
				ID:          "a1b2c3d4e5f6",
				Title:       "Test Trail",
				Description: "Test description",
			},
			wantErr: false,
		},
		{
			name: "missing ID",
			trail: Trail{
				Title:       "Test Trail",
				Description: "Test description",
			},
			wantErr: true,
		},
		{
			name: "missing title",
			trail: Trail{
				ID:          "a1b2c3d4e5f6",
				Description: "Test description",
			},
			wantErr: true,
		},
		{
			name: "missing description",
			trail: Trail{
				ID:    "a1b2c3d4e5f6",
				Title: "Test Trail",
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			err := tt.trail.Validate()
			if (err != nil) != tt.wantErr {
				t.Errorf("Validate() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestTrail_GetBranch(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		trail Trail
		want  string
	}{
		{
			name: "custom branch",
			trail: Trail{
				ID:     "a1b2c3d4e5f6",
				Branch: "feature/custom",
			},
			want: "feature/custom",
		},
		{
			name: "default branch",
			trail: Trail{
				ID: "a1b2c3d4e5f6",
			},
			want: "trail/a1b2c3d4e5f6",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := tt.trail.GetBranch(); got != tt.want {
				t.Errorf("GetBranch() = %q, want %q", got, tt.want)
			}
		})
	}
}

