package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

// ProofConfig defines a single proof (validation check) to run.
type ProofConfig struct {
	// Type is the proof identifier (e.g., "test", "lint", "typecheck")
	Type string `json:"type"`
	// Command is the shell command to execute
	Command string `json:"command"`
	// Required indicates if this proof must pass for validation to succeed
	Required bool `json:"required"`
}

// ValidationConfig holds the validation configuration from settings.
type ValidationConfig struct {
	// Enabled controls whether validation runs automatically
	Enabled bool `json:"enabled"`
	// Proofs is the list of proof checks to run
	Proofs []ProofConfig `json:"proofs"`
}

// ProofResult holds the result of running a single proof.
type ProofResult struct {
	Type     string        `json:"type"`
	Command  string        `json:"command"`
	Passed   bool          `json:"passed"`
	Required bool          `json:"required"`
	Output   string        `json:"output,omitempty"`
	Error    string        `json:"error,omitempty"`
	Duration time.Duration `json:"duration"`
}

// ValidationResult holds the complete validation results.
type ValidationResult struct {
	Passed    bool          `json:"passed"`
	Proofs    []ProofResult `json:"proofs"`
	Duration  time.Duration `json:"duration"`
	Timestamp time.Time     `json:"timestamp"`
}

// DefaultValidationConfig returns the default validation configuration.
func DefaultValidationConfig() *ValidationConfig {
	return &ValidationConfig{
		Enabled: false,
		Proofs: []ProofConfig{
			{Type: "test", Command: "mise run test", Required: true},
			{Type: "lint", Command: "mise run lint", Required: true},
		},
	}
}

func newValidateCmd() *cobra.Command {
	var (
		jsonOutput bool
		proofTypes []string
	)

	cmd := &cobra.Command{
		Use:    "validate",
		Short:  "Run validation proofs on the codebase",
		Hidden: true, // Hidden experimental command
		Long: `Run configured validation proofs to verify code quality.

This command runs the validation proofs configured in .entire/settings.json
under the "validation" key. Each proof is a command that must exit with
status 0 to pass.

Example configuration in .entire/settings.json:
  {
    "validation": {
      "enabled": true,
      "proofs": [
        {"type": "test", "command": "mise run test", "required": true},
        {"type": "lint", "command": "mise run lint", "required": true},
        {"type": "typecheck", "command": "go build ./...", "required": true}
      ]
    }
  }

This is an experimental feature for autonomous validation workflows.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runValidate(cmd.OutOrStdout(), cmd.ErrOrStderr(), jsonOutput, proofTypes)
		},
	}

	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output results as JSON")
	cmd.Flags().StringSliceVar(&proofTypes, "proof", nil, "Run only specific proof types (can be repeated)")

	return cmd
}

func runValidate(stdout, stderr io.Writer, jsonOutput bool, filterProofs []string) error {
	// Check if we're in a git repository
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("not in a git repository: %w", err)
	}

	// Load validation config
	config, err := loadValidationConfig()
	if err != nil {
		return fmt.Errorf("failed to load validation config: %w", err)
	}

	if len(config.Proofs) == 0 {
		if jsonOutput {
			result := &ValidationResult{
				Passed:    true,
				Proofs:    []ProofResult{},
				Timestamp: time.Now(),
			}
			return outputJSON(stdout, result)
		}
		fmt.Fprintln(stdout, "No validation proofs configured.")
		fmt.Fprintln(stdout, "\nAdd proofs to .entire/settings.json:")
		fmt.Fprintln(stdout, `  "validation": {`)
		fmt.Fprintln(stdout, `    "enabled": true,`)
		fmt.Fprintln(stdout, `    "proofs": [`)
		fmt.Fprintln(stdout, `      {"type": "test", "command": "mise run test", "required": true}`)
		fmt.Fprintln(stdout, `    ]`)
		fmt.Fprintln(stdout, `  }`)
		return nil
	}

	// Filter proofs if specific types requested
	proofsToRun := config.Proofs
	if len(filterProofs) > 0 {
		proofsToRun = filterProofsByType(config.Proofs, filterProofs)
		if len(proofsToRun) == 0 {
			return fmt.Errorf("no matching proofs found for types: %v", filterProofs)
		}
	}

	// Run validation
	result := runProofs(stdout, stderr, repoRoot, proofsToRun, jsonOutput)

	if jsonOutput {
		return outputJSON(stdout, result)
	}

	// Print summary
	printValidationSummary(stdout, result)

	if !result.Passed {
		return NewSilentError(errors.New("validation failed"))
	}
	return nil
}

func loadValidationConfig() (*ValidationConfig, error) {
	settings, err := LoadEntireSettings()
	if err != nil {
		return DefaultValidationConfig(), nil //nolint:nilerr // use defaults on error
	}

	// Check if validation is configured in strategy_options
	if settings.StrategyOptions == nil {
		return DefaultValidationConfig(), nil
	}

	validationRaw, ok := settings.StrategyOptions["validation"]
	if !ok {
		return DefaultValidationConfig(), nil
	}

	// Convert to JSON and back to parse into ValidationConfig
	data, err := json.Marshal(validationRaw)
	if err != nil {
		return nil, fmt.Errorf("marshaling validation config: %w", err)
	}

	var config ValidationConfig
	if err := json.Unmarshal(data, &config); err != nil {
		return nil, fmt.Errorf("parsing validation config: %w", err)
	}

	return &config, nil
}

func filterProofsByType(proofs []ProofConfig, types []string) []ProofConfig {
	typeSet := make(map[string]bool)
	for _, t := range types {
		typeSet[strings.ToLower(t)] = true
	}

	var filtered []ProofConfig
	for _, p := range proofs {
		if typeSet[strings.ToLower(p.Type)] {
			filtered = append(filtered, p)
		}
	}
	return filtered
}

func runProofs(stdout, stderr io.Writer, repoRoot string, proofs []ProofConfig, quiet bool) *ValidationResult {
	start := time.Now()
	result := &ValidationResult{
		Passed:    true,
		Proofs:    make([]ProofResult, 0, len(proofs)),
		Timestamp: start,
	}

	for i, proof := range proofs {
		if !quiet {
			fmt.Fprintf(stdout, "\n[%d/%d] Running %s: %s\n", i+1, len(proofs), proof.Type, proof.Command)
		}

		proofResult := runSingleProof(repoRoot, proof)
		result.Proofs = append(result.Proofs, proofResult)

		if !quiet {
			if proofResult.Passed {
				fmt.Fprintf(stdout, "  ✓ PASSED (%s)\n", proofResult.Duration.Round(time.Millisecond))
			} else {
				fmt.Fprintf(stdout, "  ✗ FAILED (%s)\n", proofResult.Duration.Round(time.Millisecond))
				if proofResult.Output != "" {
					// Print last 20 lines of output
					lines := strings.Split(strings.TrimSpace(proofResult.Output), "\n")
					if len(lines) > 20 {
						fmt.Fprintf(stderr, "  ... (%d lines truncated)\n", len(lines)-20)
						lines = lines[len(lines)-20:]
					}
					for _, line := range lines {
						fmt.Fprintf(stderr, "  │ %s\n", line)
					}
				}
				if proofResult.Error != "" {
					fmt.Fprintf(stderr, "  Error: %s\n", proofResult.Error)
				}
			}
		}

		// Update overall pass status
		if !proofResult.Passed && proof.Required {
			result.Passed = false
		}
	}

	result.Duration = time.Since(start)
	return result
}

func runSingleProof(repoRoot string, proof ProofConfig) ProofResult {
	start := time.Now()
	result := ProofResult{
		Type:     proof.Type,
		Command:  proof.Command,
		Required: proof.Required,
	}

	// Create command with shell
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
	defer cancel()

	cmd := exec.CommandContext(ctx, "sh", "-c", proof.Command) //nolint:gosec // command is user-configured in settings.json
	cmd.Dir = repoRoot

	// Capture output
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	result.Duration = time.Since(start)

	// Combine stdout and stderr for output
	output := stdout.String()
	if stderr.Len() > 0 {
		if output != "" {
			output += "\n"
		}
		output += stderr.String()
	}
	result.Output = strings.TrimSpace(output)

	if err != nil {
		result.Passed = false
		if ctx.Err() == context.DeadlineExceeded {
			result.Error = "command timed out after 10 minutes"
		} else {
			result.Error = err.Error()
		}
	} else {
		result.Passed = true
	}

	return result
}

func printValidationSummary(w io.Writer, result *ValidationResult) {
	fmt.Fprintln(w, "\n"+strings.Repeat("─", 50))
	fmt.Fprintln(w, "Validation Summary")
	fmt.Fprintln(w, strings.Repeat("─", 50))

	passed := 0
	failed := 0
	for _, p := range result.Proofs {
		status := "✓"
		if !p.Passed {
			status = "✗"
			failed++
		} else {
			passed++
		}
		reqLabel := ""
		if !p.Required {
			reqLabel = " (optional)"
		}
		fmt.Fprintf(w, "  %s %s%s\n", status, p.Type, reqLabel)
	}

	fmt.Fprintln(w, strings.Repeat("─", 50))
	fmt.Fprintf(w, "Total: %d passed, %d failed (%.1fs)\n", passed, failed, result.Duration.Seconds())

	if result.Passed {
		fmt.Fprintln(w, "\n✓ All required proofs passed")
	} else {
		fmt.Fprintln(w, "\n✗ Validation failed - required proofs did not pass")
	}
}

func outputJSON(w io.Writer, result *ValidationResult) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(result); err != nil {
		return fmt.Errorf("encoding validation result: %w", err)
	}
	return nil
}

package trail

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// RunnerConfig holds configuration for the trail runner.
type RunnerConfig struct {
	// PollInterval is how often to check for new trails in daemon mode.
	PollInterval time.Duration

	// MaxConcurrent is the maximum number of trails to run concurrently.
	// Currently only 1 is supported.
	MaxConcurrent int

	// Daemon enables continuous polling mode.
	Daemon bool

	// Agent is the agent CLI to use (e.g., "claude").
	Agent string

	// Model is the optional model override for the agent.
	Model string

	// Timeout is the maximum time to wait for a single trail execution.
	Timeout time.Duration

	// DryRun prevents actual execution, just prints what would be done.
	DryRun bool
}

// DefaultRunnerConfig returns the default runner configuration.
func DefaultRunnerConfig() RunnerConfig {
	return RunnerConfig{
		PollInterval:  30 * time.Second,
		MaxConcurrent: 1,
		Daemon:        false,
		Agent:         "claude",
		Model:         "",
		Timeout:       30 * time.Minute,
		DryRun:        false,
	}
}

// Runner executes trails by discovering open tasks, claiming them,
// creating worktrees, running agents, and updating state.
type Runner struct {
	repo      *git.Repository
	repoRoot  string
	store     *Store
	state     *StateManager
	discovery *Discovery
	worktree  *WorktreeManager
	config    RunnerConfig
}

// NewRunner creates a new trail runner.
func NewRunner(repo *git.Repository, repoRoot string, config RunnerConfig) *Runner {
	return &Runner{
		repo:      repo,
		repoRoot:  repoRoot,
		store:     NewStore(repo),
		state:     NewStateManager(repo),
		discovery: NewDiscovery(repo),
		worktree:  NewWorktreeManager(repoRoot),
		config:    config,
	}
}

// RunResult holds the result of running a single trail.
type RunResult struct {
	Trail    *Trail
	Success  bool
	Output   string
	Error    error
	Duration time.Duration
}

// Start runs the trail runner in daemon mode, continuously polling for new trails.
func (r *Runner) Start(ctx context.Context) error {
	logging.Info(ctx, "trail runner started",
		slog.Duration("poll_interval", r.config.PollInterval),
		slog.Bool("daemon", r.config.Daemon),
	)

	for {
		// Run one iteration
		results, err := r.RunOnce(ctx)
		if err != nil {
			logging.Error(ctx, "runner iteration failed", slog.String("error", err.Error()))
		}

		for _, result := range results {
			if result.Success {
				logging.Info(ctx, "trail completed successfully",
					slog.String("trail_id", result.Trail.ID.String()),
					slog.Duration("duration", result.Duration),
				)
			} else {
				logging.Error(ctx, "trail failed",
					slog.String("trail_id", result.Trail.ID.String()),
					slog.String("error", result.Error.Error()),
				)
			}
		}

		if !r.config.Daemon {
			return nil
		}

		// Wait before next poll
		select {
		case <-ctx.Done():
			logging.Info(ctx, "trail runner stopping")
			return fmt.Errorf("trail runner stopped: %w", ctx.Err())
		case <-time.After(r.config.PollInterval):
			// Continue to next iteration
		}
	}
}

// RunOnce performs a single iteration: find open trails and run them.
func (r *Runner) RunOnce(ctx context.Context) ([]RunResult, error) {
	// Find open trails
	openTrails, err := r.discovery.FindOpen(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to find open trails: %w", err)
	}

	if len(openTrails) == 0 {
		logging.Debug(ctx, "no open trails found")
		return nil, nil
	}

	logging.Info(ctx, "found open trails", slog.Int("count", len(openTrails)))

	var results []RunResult

	// Run trails up to max concurrent (currently only 1)
	maxToRun := min(len(openTrails), r.config.MaxConcurrent)
	for i := range maxToRun {
		trail := openTrails[i].Trail
		result := r.RunTrail(ctx, &trail)
		results = append(results, result)
	}

	return results, nil
}

// RunTrail executes a single trail.
func (r *Runner) RunTrail(ctx context.Context, trail *Trail) RunResult {
	start := time.Now()
	result := RunResult{Trail: trail}

	ctx = logging.WithComponent(ctx, "trail-runner")

	logging.Info(ctx, "starting trail execution",
		slog.String("trail_id", trail.ID.String()),
		slog.String("title", trail.Title),
	)

	if r.config.DryRun {
		logging.Info(ctx, "dry run - skipping execution")
		result.Success = true
		result.Output = "dry run"
		result.Duration = time.Since(start)
		return result
	}

	// Create worktree and get initial branch head
	worktreePath, branchHead, err := r.setupWorktree(ctx, trail)
	if err != nil {
		result.Error = fmt.Errorf("failed to setup worktree: %w", err)
		result.Duration = time.Since(start)
		return result
	}

	// Claim the trail
	if err := r.state.Claim(ctx, trail.ID, branchHead); err != nil {
		if errors.Is(err, ErrAlreadyClaimed) {
			logging.Info(ctx, "trail already claimed, skipping",
				slog.String("trail_id", trail.ID.String()),
			)
		}
		result.Error = err
		result.Duration = time.Since(start)
		// Clean up worktree if we couldn't claim
		if removeErr := r.worktree.Remove(ctx, trail.ID); removeErr != nil {
			logging.Warn(ctx, "failed to remove worktree after claim failure",
				slog.String("trail_id", trail.ID.String()),
				slog.String("error", removeErr.Error()),
			)
		}
		return result
	}

	// Run the agent
	output, agentErr := r.runAgent(ctx, trail, worktreePath)
	result.Output = output

	// Get final branch head
	finalHead, headErr := r.worktree.GetHeadCommit(ctx, trail.ID)
	finalHeadHash := plumbing.NewHash(finalHead)
	if headErr != nil || finalHeadHash.IsZero() {
		// Fall back to initial branch head if we can't get the current
		finalHeadHash = branchHead
	}

	// Update state based on result
	if agentErr != nil {
		result.Error = agentErr
		result.Success = false
		if err := r.state.Fail(ctx, trail.ID, finalHeadHash); err != nil {
			logging.Error(ctx, "failed to mark trail as failed",
				slog.String("trail_id", trail.ID.String()),
				slog.String("error", err.Error()),
			)
		}
	} else {
		result.Success = true
		if err := r.state.Complete(ctx, trail.ID, finalHeadHash); err != nil {
			logging.Error(ctx, "failed to mark trail as completed",
				slog.String("trail_id", trail.ID.String()),
				slog.String("error", err.Error()),
			)
		}
	}

	// Clean up worktree
	if err := r.worktree.Remove(ctx, trail.ID); err != nil {
		logging.Warn(ctx, "failed to remove worktree",
			slog.String("trail_id", trail.ID.String()),
			slog.String("error", err.Error()),
		)
	}

	result.Duration = time.Since(start)

	logging.Info(ctx, "trail execution finished",
		slog.String("trail_id", trail.ID.String()),
		slog.Bool("success", result.Success),
		slog.Duration("duration", result.Duration),
	)

	return result
}

// setupWorktree creates a worktree for the trail and returns the path and branch head.
func (r *Runner) setupWorktree(ctx context.Context, trail *Trail) (string, plumbing.Hash, error) {
	branch := trail.GetBranch()

	// Ensure .worktrees is in .gitignore
	if err := EnsureWorktreesIgnored(r.repoRoot); err != nil {
		logging.Warn(ctx, "failed to ensure worktrees ignored",
			slog.String("error", err.Error()),
		)
	}

	// Create the worktree
	worktreePath, err := r.worktree.Create(ctx, trail.ID, branch, trail.BaseBranch)
	if err != nil {
		return "", plumbing.ZeroHash, err
	}

	// Get the branch head
	headCommit, err := r.worktree.GetHeadCommit(ctx, trail.ID)
	if err != nil {
		return "", plumbing.ZeroHash, fmt.Errorf("failed to get branch head: %w", err)
	}

	return worktreePath, plumbing.NewHash(headCommit), nil
}

// runAgent executes the agent CLI with the trail description.
func (r *Runner) runAgent(ctx context.Context, trail *Trail, worktreePath string) (string, error) {
	// Build the prompt from trail description
	prompt := trail.Description

	// Build command arguments
	args := []string{}

	// Add model if specified
	if r.config.Model != "" {
		args = append(args, "--model", r.config.Model)
	}

	// Add prompt
	args = append(args, "-p", prompt)

	// Create context with timeout
	if r.config.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, r.config.Timeout)
		defer cancel()
	}

	logging.Debug(ctx, "running agent",
		slog.String("agent", r.config.Agent),
		slog.String("worktree", worktreePath),
	)

	//nolint:gosec // args are constructed from trusted config
	cmd := exec.CommandContext(ctx, r.config.Agent, args...)
	cmd.Dir = worktreePath
	cmd.Env = append(os.Environ(),
		// Ensure entire hooks are enabled in the worktree
		"ENTIRE_ENABLED=1",
	)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()

	output := stdout.String()
	if stderr.Len() > 0 {
		if output != "" {
			output += "\n"
		}
		output += stderr.String()
	}

	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return output, fmt.Errorf("agent timed out after %s", r.config.Timeout)
		}
		return output, fmt.Errorf("agent failed: %s: %w", strings.TrimSpace(stderr.String()), err)
	}

	return output, nil
}

// RunTrailByID executes a trail by its ID.
func (r *Runner) RunTrailByID(ctx context.Context, id TrailID) (RunResult, error) {
	trail, err := r.store.Get(ctx, id)
	if err != nil {
		return RunResult{}, fmt.Errorf("failed to get trail: %w", err)
	}
	if trail == nil {
		return RunResult{}, fmt.Errorf("trail not found: %s", id)
	}

	return r.RunTrail(ctx, trail), nil
}

