	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return "", fmt.Errorf("agent timed out after %s", r.config.Timeout)
		}
		return "", fmt.Errorf("agent failed: %w", err)
	}

	return result.Text, nil
}

