		}
		//nolint:gosec // repoRoot is from trusted config
		cmd = exec.CommandContext(ctx, "go", "run", filepath.Join(repoRoot, "cmd/entire"), "validate", "--json")
	} else {
		entireCLI := r.config.EntireCLI
		if entireCLI == "" {
			entireCLI = "entire"
		}
		//nolint:gosec // entireCLI is from trusted config
		cmd = exec.CommandContext(ctx, entireCLI, "validate", "--json")
	}
	cmd.Dir = worktreePath

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()

	// Combine output for logging
	output := stdout.String()
	if stderr.Len() > 0 {
