func runTrailRunnerStart(cmd *cobra.Command, daemon bool, pollInterval time.Duration, agentName, model string, timeout time.Duration, dryRun bool, maxAttempts int, localDev bool) error {
	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repository root: %w", err)
	}

	config := trail.RunnerConfig{
		PollInterval:  pollInterval,
		MaxConcurrent: 1,
		Daemon:        daemon,
		AgentName:     agent.AgentName(agentName),
		Model:         model,
		Timeout:       timeout,
		DryRun:        dryRun,
		MaxAttempts:   maxAttempts,
		LocalDev:      localDev,
		RepoRoot:      repoRoot,
	}

	runner := trail.NewRunner(repo, repoRoot, config)
	ctx := cmd.Context()

	if daemon {
