		fmt.Fprintf(cmd.OutOrStdout(), "Labels: %s\n", strings.Join(t.Labels, ", "))
	}
	if len(t.Assignees) > 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "Assignees: %s\n", strings.Join(t.Assignees, ", "))
	}

	fmt.Fprintf(cmd.OutOrStdout(), "\nDescription:\n%s\n", t.Description)

	return nil
}

func runTrailCreate(cmd *cobra.Command, title, branch, baseBranch string, labels []string) error {
	var description string

	// Interactive mode if no title provided
	if title == "" {
		var err error
		title, description, branch, baseBranch, err = runTrailCreateInteractive()
		if err != nil {
			return err
		}
	} else {
		// Get description interactively
		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewText().
					Title("Description").
					Description("Describe the task for the agent").
					Value(&description).
					CharLimit(4000),
			),
		)
		if err := form.Run(); err != nil {
			return fmt.Errorf("cancelled: %w", err)
		}
	}

	if description == "" {
		return errors.New("description is required")
	}

	// Generate trail ID
	id, err := trail.GenerateTrailID()
	if err != nil {
		return fmt.Errorf("failed to generate trail ID: %w", err)
	}

	// Create trail
	t := &trail.Trail{
		ID:          id,
		Title:       title,
		Description: description,
		Branch:      branch,
		BaseBranch:  baseBranch,
		Labels:      labels,
	}

	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	store := trail.NewStore(repo)
	ctx := context.Background()

	if err := store.Create(ctx, t); err != nil {
		return fmt.Errorf("failed to create trail: %w", err)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "Created trail: %s\n", id)
	fmt.Fprintf(cmd.OutOrStdout(), "Branch: %s\n", t.GetBranch())
	fmt.Fprintf(cmd.OutOrStdout(), "\nRun the trail with: entire trail run %s\n", id)

	return nil
}

func runTrailCreateInteractive() (title, description, branch, baseBranch string, err error) {
	// Get current branch and available branches for selection
	repo, err := openRepository()
	if err != nil {
		return "", "", "", "", fmt.Errorf("failed to open repository: %w", err)
	}

	currentBranch, defaultBranch, allBranches := getBranchInfo(repo)

	// Build base branch options
	var baseBranchChoice string
	baseOptions := []huh.Option[string]{
		huh.NewOption("Current branch ("+currentBranch+")", "current"),
		huh.NewOption("Default branch ("+defaultBranch+")", "default"),
		huh.NewOption("Pick from branches...", "pick"),
	}

	// First form: title, description, base branch choice
	form1 := NewAccessibleForm(
		huh.NewGroup(
			huh.NewInput().
				Title("Title").
				Description("Brief title for the task").
				Value(&title),
			huh.NewText().
				Title("Description").
				Description("Describe the task for the agent").
				Value(&description).
				CharLimit(4000),
			huh.NewInput().
				Title("Branch").
				Description("Branch name for this trail (leave empty for auto-generated)").
				Value(&branch),
			huh.NewSelect[string]().
				Title("Base Branch").
				Description("Which branch should the trail start from?").
				Options(baseOptions...).
				Value(&baseBranchChoice),
		),
	)

	if err := form1.Run(); err != nil {
		return "", "", "", "", fmt.Errorf("cancelled: %w", err)
	}

	if title == "" {
		return "", "", "", "", errors.New("title is required")
	}

	// Resolve base branch choice
	switch baseBranchChoice {
	case "current":
		baseBranch = currentBranch
	case "default":
		baseBranch = defaultBranch
	case "pick":
		// Show branch picker with autocomplete
		branchOptions := make([]huh.Option[string], len(allBranches))
		for i, b := range allBranches {
			branchOptions[i] = huh.NewOption(b, b)
		}

		form2 := NewAccessibleForm(
			huh.NewGroup(
				huh.NewSelect[string]().
					Title("Select Branch").
					Description("Choose the base branch").
					Options(branchOptions...).
					Value(&baseBranch).
					Filtering(true).
					Height(10),
			),
		)

		if err := form2.Run(); err != nil {
			return "", "", "", "", fmt.Errorf("cancelled: %w", err)
		}
	}

	return title, description, branch, baseBranch, nil
}

// getBranchInfo returns current branch, default branch, and all branch names.
func getBranchInfo(repo *git.Repository) (current, defaultBr string, all []string) {
	// Get current branch
	head, err := repo.Head()
	if err == nil && head.Name().IsBranch() {
		current = head.Name().Short()
	} else {
		current = "HEAD"
	}

	// Get all branches
	branches, err := repo.Branches()
	if err == nil {
		_ = branches.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // Collecting branches best-effort; partial list is acceptable
			name := ref.Name().Short()
			all = append(all, name)
			return nil
		})
	}

	// Determine default branch from origin/HEAD
	defaultBr = strategy.GetDefaultBranchName(repo)
	if defaultBr == "" {
		defaultBr = branchMain // Fallback
	}

	return current, defaultBr, all
}

// getDefaultBranch returns the repository's default branch name.
// First tries to read origin/HEAD, then falls back to checking main/master.
func getDefaultBranch(repo *git.Repository) string {
	// Try to get the symbolic reference for origin/HEAD
	originHead, err := repo.Reference(plumbing.ReferenceName("refs/remotes/origin/HEAD"), true)
	if err == nil {
		// Extract branch name from refs/remotes/origin/main
		name := originHead.Name().Short()
		// name will be "origin/main" or "origin/master", extract the last part
		parts := strings.Split(name, "/")
		if len(parts) > 0 {
			return parts[len(parts)-1]
		}
	}

	// Fall back to checking common default branch names
	for _, branch := range []string{branchMain, branchMaster} {
		_, err := repo.Reference(plumbing.NewBranchReferenceName(branch), true)
		if err == nil {
			return branch
		}
	}

	return branchMain // Ultimate fallback
}

func runTrailDelete(cmd *cobra.Command, idStr string, force bool) error {
	id, err := trail.NewTrailID(idStr)
	if err != nil {
		return err //nolint:wrapcheck // validation error
	}

	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	store := trail.NewStore(repo)
	ctx := context.Background()

	// Check if trail exists
	t, err := store.Get(ctx, id)
	if err != nil {
		return fmt.Errorf("failed to get trail: %w", err)
	}
	if t == nil {
		return fmt.Errorf("trail not found: %s", id)
	}

	// Confirm deletion
	if !force {
		var confirm bool
		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewConfirm().
					Title(fmt.Sprintf("Delete trail %s?", id)).
					Description(t.Title).
					Value(&confirm),
			),
		)
		if err := form.Run(); err != nil {
			return fmt.Errorf("cancelled: %w", err)
		}
		if !confirm {
			fmt.Fprintln(cmd.OutOrStdout(), "Cancelled.")
			return nil
		}
	}

	// Also reset state refs
	state := trail.NewStateManager(repo)
	if err := state.Reset(ctx, id); err != nil {
		// Non-fatal, continue with deletion
		fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to reset state refs: %v\n", err)
	}

	if err := store.Delete(ctx, id); err != nil {
		return fmt.Errorf("failed to delete trail: %w", err)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "Deleted trail: %s\n", id)
	return nil
}

func runTrailReset(cmd *cobra.Command, idStr string) error {
	id, err := trail.NewTrailID(idStr)
	if err != nil {
		return err //nolint:wrapcheck // validation error
	}

	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	state := trail.NewStateManager(repo)
	ctx := context.Background()

	if err := state.Reset(ctx, id); err != nil {
		return fmt.Errorf("failed to reset trail state: %w", err)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "Reset trail: %s (now open)\n", id)
	return nil
}

func parseTrailState(s string) (trail.TrailState, error) {
	switch strings.ToLower(s) {
	case "open":
		return trail.TrailStateOpen, nil
	case "in_progress", "inprogress", "claimed":
		return trail.TrailStateInProgress, nil
	case "completed", "done":
		return trail.TrailStateCompleted, nil
	case "failed", "error":
		return trail.TrailStateFailed, nil
	default:
		return "", fmt.Errorf("invalid status: %s (valid: open, in_progress, completed, failed)", s)
	}
}

func formatTrailState(state trail.TrailState) string {
	switch state {
	case trail.TrailStateOpen:
		return "open"
	case trail.TrailStateInProgress:
		return "in_progress"
	case trail.TrailStateCompleted:
		return "completed"
	case trail.TrailStateFailed:
		return "failed"
	default:
		return string(state)
	}
}

